"""Generated by the NL to Flow Diagram Encoder Pipeline."""

def unnamed_function(s):
    chars = list(s)
    left = 0
    right = (len(s) - 1)
    while (left < right):
        temp_var = chars[left]
        chars[left] = chars[right]
        chars[right] = temp_var
        left = (left + 1)
        right = (right - 1)
    return ''.join(chars)
